const items = $input.all();
const candidates = [];

function easternTodayUtc() {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/New_York',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    })
      .formatToParts(new Date())
      .filter((part) => part.type !== 'literal')
      .map((part) => [part.type, part.value])
  );

  return Date.UTC(
    Number(parts.year),
    Number(parts.month) - 1,
    Number(parts.day)
  );
}

const todayUtc = easternTodayUtc();
const dayMs = 24 * 60 * 60 * 1000;

for (let index = 0; index < items.length; index++) {
  const binary = items[index].binary?.data;
  if (!binary) continue;

  const fileName =
    binary.fileName ||
    binary.filePath?.split('/').pop() ||
    `theme-list-${index}.txt`;

  const match = fileName.match(
    /theme-list-model-eval-qwen35-(\d{4}-\d{2}-\d{2})\.txt$/i
  );
  if (!match) continue;

  const [year, month, day] = match[1].split('-').map(Number);
  const fileDateUtc = Date.UTC(year, month - 1, day);
  const ageDays = Math.floor((todayUtc - fileDateUtc) / dayMs);

  // Only use a current/recent theme file. Future-dated files and files
  // older than three calendar days are excluded.
  if (ageDays < 0 || ageDays > 3) continue;

  const buffer = await this.helpers.getBinaryDataBuffer(index, 'data');
  candidates.push({
    fileName,
    fileDate: match[1],
    ageDays,
    text: buffer.toString('utf-8'),
  });
}

if (!candidates.length) {
  throw new Error(
    'No qwen3.5 model-eval theme list file from the last 3 days was found.'
  );
}

candidates.sort((a, b) => {
  const dateCompare = b.fileDate.localeCompare(a.fileDate);
  return dateCompare || b.fileName.localeCompare(a.fileName);
});

const latest = candidates[0];
const privacyProof = JSON.parse($('Require Approved Privacy Artifact').first().json.stdout);
if (latest.fileName !== privacyProof.fileName) throw Error('Privacy artifact selection mismatch');

const blockedPatterns = [
  /\bemotionally unstable\b/i,
  /\bpersonnel\b/i,
  /\bemployee performance\b/i,
  /\bdisciplin/i,
  /\btermination\b/i,
  /\bcompensation\b/i,
  /\bsalary\b/i,
  /\bcontract negotiation/i,
  /\bsales pipeline\b/i,
  /\bclient engagement/i,
];

const seen = new Set();
const rawThemes = [];

for (const rawLine of latest.text.split(/\r?\n/)) {
  const line = rawLine.trim();
  if (!line.startsWith('-')) continue;

  const theme = line.replace(/^-\s*/, '').replace(/\s+/g, ' ').trim();
  if (!theme || theme === '(no public-safe theme found)') continue;
  if (blockedPatterns.some((pattern) => pattern.test(theme))) continue;

  const key = theme.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  if (!key || seen.has(key)) continue;
  seen.add(key);
  rawThemes.push(theme);
}

if (!rawThemes.length) {
  throw new Error(`No usable public themes were found in ${latest.fileName}.`);
}

return [
  {
    json: {
      privacyProof,
      sourceThemeFile: latest.fileName,
      sourceThemeDate: latest.fileDate,
      sourceThemeAgeDays: latest.ageDays,
      rawThemeCount: rawThemes.length,
      rawThemes,
    },
  },
];

