function parseJson(value) {
  const text = String(value || '').replace(/```(?:json)?|```/gi, '').trim();
  try {
    return JSON.parse(text);
  } catch {
    const first = text.indexOf('{');
    const last = text.lastIndexOf('}');
    if (first >= 0 && last > first) return JSON.parse(text.slice(first, last + 1));
    throw new Error('Local inference did not return valid JSON for the content brief.');
  }
}

function text(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function sourcePlainText(value) {
  return text(value)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&#x27;|&#39;|&apos;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function list(value) {
  return Array.isArray(value) ? value.filter(Boolean) : [];
}

function canonicalUrl(value) {
  try {
    const url = new URL(value);
    url.hash = '';
    const tracking = [
      'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content',
      'gclid', 'fbclid', 'mc_cid', 'mc_eid',
    ];
    for (const name of tracking) url.searchParams.delete(name);
    url.hostname = url.hostname.toLowerCase();
    return url.toString().replace(/\/$/, '');
  } catch {
    return text(value);
  }
}


function hostnameFromUrl(value) {
  const match = String(value || '').trim().match(/^https?:\/\/([^\/?#]+)/i);
  if (!match) return '';
  return match[1].split('@').pop().split(':')[0].toLowerCase().replace(/^www\./, '');
}


function sourceFamily(value) {
  const host = hostnameFromUrl(value);
  if (!host) return '';
  const parts = host.split('.').filter(Boolean);
  if (parts.length <= 2) return host;
  const suffix = parts.slice(-2).join('.');
  if (['co.uk', 'org.uk', 'gov.uk', 'ac.uk', 'com.au', 'org.au', 'gov.au'].includes(suffix)) {
    return parts.slice(-3).join('.');
  }
  return suffix;
}

function matchesDomain(host, domain) {
  return host === domain || host.endsWith(`.${domain}`);
}

const primaryDomains = [
  'cisa.gov', 'nist.gov', 'nvd.nist.gov', 'sec.gov', 'ftc.gov', 'fcc.gov',
  'hhs.gov', 'ed.gov', 'cyber.gc.ca', 'microsoft.com', 'learn.microsoft.com',
  'aws.amazon.com', 'openai.com', 'cloud.google.com', 'google.com', 'github.com',
  'apple.com', 'cisco.com', 'paloaltonetworks.com', 'crowdstrike.com',
  'fortinet.com', 'broadcom.com', 'vmware.com', 'redhat.com', 'oracle.com',
  'ibm.com', 'cloudflare.com', 'okta.com', 'akamai.com', 'commvault.com',
  'deloitte.com', 'geoserver.org',
];

const credibleDomains = [
  'reuters.com', 'apnews.com', 'bloomberg.com', 'ft.com', 'wsj.com',
  'bleepingcomputer.com', 'therecord.media', 'cyberscoop.com', 'wired.com',
  'arstechnica.com', 'darkreading.com', 'securityweek.com', 'theregister.com',
  'techcrunch.com', 'thehackernews.com', 'helpnetsecurity.com', 'csoonline.com',
  'cio.com', 'infoworld.com', 'networkworld.com', 'scworld.com', 'axios.com',
  'bankinfosecurity.com', 'govinfosecurity.com', 'crn.com', 'law.com',
  'healthcareitnews.com', 'healthitsecurity.com', 'retaildive.com',
  'channelinsider.com',
];

function classifySource(value) {
  const host = hostnameFromUrl(value);
  if (host.endsWith('.gov') || host.endsWith('.gov.uk')) return 'primary';
  if (primaryDomains.some((domain) => matchesDomain(host, domain))) return 'primary';
  if (credibleDomains.some((domain) => matchesDomain(host, domain))) return 'credible_independent';
  return 'other';
}

function normalized(value) {
  return text(value).toLowerCase().replace(/[“”‘’]/g, "'");
}

const semanticStopWords = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'before', 'by', 'can', 'for',
  'from', 'how', 'in', 'into', 'is', 'it', 'new', 'of', 'on', 'or', 'our',
  'that', 'the', 'their', 'this', 'to', 'use', 'using', 'what', 'when', 'why',
  'with', 'your', 'ai', 'cyber', 'cybersecurity', 'security', 'technology',
  'enterprise', 'organization', 'organizations', 'management', 'manage',
  'risk', 'risks', 'system', 'systems', 'guidance', 'guide', 'framework',
  'operational', 'operations', 'leader', 'leaders', 'leadership', 'decision',
  'decisions', 'practice', 'practices', 'current', 'recent', 'official',
  'cisa', 'nist', 'microsoft',
]);

function semanticStem(value) {
  let token = text(value).toLowerCase().replace(/[^a-z0-9-]/g, '');
  if (token.length > 6 && token.endsWith('ization')) token = token.slice(0, -7) + 'ize';
  else if (token.length > 6 && token.endsWith('ation')) token = token.slice(0, -5) + 'ate';
  else if (token.length > 5 && token.endsWith('ing')) token = token.slice(0, -3);
  else if (token.length > 5 && token.endsWith('ied')) token = token.slice(0, -3) + 'y';
  else if (token.length > 4 && token.endsWith('ed')) token = token.slice(0, -2);
  else if (token.length > 4 && token.endsWith('ies')) token = token.slice(0, -3) + 'y';
  else if (token.length > 4 && token.endsWith('s')) token = token.slice(0, -1);
  if (token.endsWith('ch')) return token;
  if (token.endsWith('tch')) return token;
  return token;
}

function semanticTokens(value) {
  return [...new Set(text(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .split(/\s+/)
    .map(semanticStem)
    .filter((token) => token.length >= 3 && !semanticStopWords.has(token)))];
}

function semanticMatchTerms(anchor, article) {
  const anchorTerms = semanticTokens(anchor);
  const sourceTerms = new Set(semanticTokens(`${article.title || ''} ${article.description || ''}`));
  return anchorTerms.filter((term) => sourceTerms.has(term));
}

function integer(value, min, max) {
  const number = Math.round(Number(value) || 0);
  return Math.max(min, Math.min(max, number));
}

function reduceToCap(scores, cap) {
  const order = [
    'novelty', 'engagementPotential', 'actionability',
    'timeliness', 'businessImpact', 'audienceFit',
  ];
  let total = Object.values(scores).reduce((sum, value) => sum + value, 0);
  let excess = Math.max(0, total - cap);
  for (const key of order) {
    if (!excess) break;
    const reduction = Math.min(scores[key], excess);
    scores[key] -= reduction;
    excess -= reduction;
  }
  total = Object.values(scores).reduce((sum, value) => sum + value, 0);
  return { scores, total };
}

const parsed = parseJson($json.choices?.[0]?.message?.content);
const source = $('Merge and Reclassify Recovery Evidence').first().json;
const articleByUrl = new Map(
  source.articles.map((article) => [canonicalUrl(article.url), article])
);
const qualifiedBundleById = new Map(
  list(source.qualifiedEvidenceBundles)
    .filter((bundle) => bundle.qualified === true && text(bundle.bundleId))
    .map((bundle) => [text(bundle.bundleId), bundle])
);
const themeSet = new Set(source.consolidatedThemes.map((theme) => normalized(theme)));
const absolutePattern = /\b(the only|only effective|only defense|the best|the biggest|biggest threat|the greatest|the most important|the key|new standard|critical need|proves?|guarantees?|immediate mitigation|stops? all|cannot fail|every day attackers|always|never)\b/i;

function validEvidenceFragment(value, article) {
  const evidence = sourcePlainText(value).replace(/^["']+|["']+$/g, '');
  const words = evidence.split(/\s+/).filter(Boolean);
  if (words.length < 5 || words.length > 18) return '';
  if (/(?:\.\.\.|…)/.test(evidence)) return '';
  const sourceText = normalized(
    `${sourcePlainText(article.title)} ${sourcePlainText(article.description)}`
  );
  return sourceText.includes(normalized(evidence)) ? evidence : '';
}

function deterministicEvidenceFragment(article, semanticAnchor) {
  const anchorTerms = new Set(semanticTokens(semanticAnchor));
  const trailingConnectors = new Set([
    'a', 'an', 'and', 'as', 'at', 'by', 'for', 'from', 'in', 'not', 'of',
    'on', 'or', 'so', 'than', 'that', 'the', 'to', 'which', 'with',
  ]);

  function candidateWindow(value, sourceType) {
    const cleanValue = sourcePlainText(value);
    if (!cleanValue) return null;
    const ellipsisIndex = cleanValue.search(/(?:\.\.\.|…)/);
    const beforeEllipsis = ellipsisIndex >= 0
      ? cleanValue.slice(0, ellipsisIndex).trim()
      : cleanValue;
    const words = beforeEllipsis.split(/\s+/).filter(Boolean);
    if (words.length < 5) return null;

    const matchingIndexes = [];
    for (let index = 0; index < words.length; index++) {
      const wordTerms = semanticTokens(words[index]);
      if (wordTerms.some((term) => anchorTerms.has(term))) matchingIndexes.push(index);
    }

    let start = 0;
    if (matchingIndexes.length) {
      start = Math.max(0, matchingIndexes[0] - 5);
      if (start + 18 > words.length) start = Math.max(0, words.length - 18);
    }
    const fragmentWords = words.slice(start, start + 18);
    while (fragmentWords.length > 5) {
      const tail = fragmentWords[fragmentWords.length - 1]
        .toLowerCase().replace(/[^a-z]/g, '');
      if (!trailingConnectors.has(tail)) break;
      fragmentWords.pop();
    }
    const fragment = fragmentWords.join(' ').replace(/[,:;]+$/, '');
    const evidence = validEvidenceFragment(fragment, article);
    if (!evidence) return null;
    const evidenceTerms = semanticTokens(evidence);
    const semanticMatchCount = evidenceTerms.filter((term) => anchorTerms.has(term)).length;
    const beforeEllipsisPenalty = ellipsisIndex >= 0 ? 10 : 0;
    const titlePreference = sourceType === 'title' ? 2 : 0;
    return {
      evidence,
      fragmentSource: `${sourceType}_semantic_window${ellipsisIndex >= 0 ? '_before_ellipsis' : ''}`,
      score: semanticMatchCount * 10 + titlePreference - beforeEllipsisPenalty,
    };
  }

  const candidates = [
    candidateWindow(article.title, 'title'),
    candidateWindow(article.description, 'description'),
  ].filter(Boolean).sort((left, right) =>
    right.score - left.score || right.evidence.length - left.evidence.length
  );
  return candidates[0] || { evidence: '', fragmentSource: '' };
}

function validateSources(candidate) {
  const output = [];
  const seen = new Set();

  for (const proposed of list(candidate.sources)) {
    const url = canonicalUrl(proposed.url);
    const article = articleByUrl.get(url);
    if (!article || seen.has(url)) continue;

    const suppliedEvidence = sourcePlainText(proposed.supportingEvidence)
      .replace(/^["']+|["']+$/g, '');
    const validatedEvidence = validEvidenceFragment(suppliedEvidence, article);
    const deterministic = validatedEvidence
      ? { evidence: validatedEvidence, fragmentSource: 'model' }
      : deterministicEvidenceFragment(
          article,
          `${candidate.topic || ''} ${candidate.proposedHeadline || ''}`
        );
    if (!deterministic.evidence) continue;

    const evidence = deterministic.evidence;
    const articleTitle = sourcePlainText(article.title);
    const articleDescription = sourcePlainText(article.description);
    seen.add(url);
    output.push({
      title: articleTitle,
      url: article.url,
      publisher: article.publisher,
      publishedAt: article.publishedAt,
      sourceTier: classifySource(article.url),
      supportingEvidence: evidence,
      evidenceExcerptRepaired: deterministic.fragmentSource !== 'model',
      evidenceExcerptSource: deterministic.fragmentSource,
      snippetMayBeTruncated:
        deterministic.fragmentSource.includes('before_ellipsis') ||
        /(?:\.\.\.|…)/.test(evidence) ||
        (!normalized(articleTitle).includes(normalized(evidence)) &&
        normalized(articleDescription).endsWith(normalized(evidence)) &&
        !/[.!?…]["')\]]?$/.test(articleDescription)),
    });
  }

  return output;
}

const validationStats = {
  rawCandidateCount: 0,
  normalizedCandidateCount: 0,
  duplicateTopicCount: 0,
  rejectedNoValidSources: 0,
  rejectedMissingTopic: 0,
  repairedEvidenceExcerptCount: 0,
  deterministicFallbackCandidateCount: 0,
  rejectedCandidates: [],
};

function normalizeCandidate(candidate, requestedSection) {
  const evidenceBundleId = text(candidate.evidenceBundleId);
  const selectedBundle = qualifiedBundleById.get(evidenceBundleId) || null;
  const bundleRequired = requestedSection !== 'watchlist';
  const bundleValid = Boolean(selectedBundle && selectedBundle.qualified === true);
  const candidateWithDeterministicSources = bundleValid
    ? {
        ...candidate,
        sources: list(selectedBundle.records).map((article) => ({
          title: article.title,
          url: article.url,
          publisher: article.publisher,
          publishedAt: article.publishedAt,
          supportingEvidence: '',
        })),
      }
    : candidate;
  const sources = validateSources(candidateWithDeterministicSources);
  if (!sources.length) {
    validationStats.rejectedNoValidSources += 1;
    if (validationStats.rejectedCandidates.length < 15) {
      validationStats.rejectedCandidates.push({
        requestedSection,
        topic: text(candidate.topic || candidate.proposedHeadline) || 'Untitled candidate',
        reason: 'No cited URL could be matched to a supplied record with a usable exact evidence fragment',
      });
    }
    return null;
  }
  validationStats.repairedEvidenceExcerptCount += sources
    .filter((item) => item.evidenceExcerptRepaired).length;

  const primaryFamilies = new Set(sources
    .filter((item) => item.sourceTier === 'primary')
    .map((item) => sourceFamily(item.url))
    .filter(Boolean));
  const credibleFamilies = new Set(sources
    .filter((item) => item.sourceTier === 'credible_independent')
    .map((item) => sourceFamily(item.url))
    .filter(Boolean));
  const primaryCount = primaryFamilies.size;
  const credibleCount = credibleFamilies.size;
  const rawHeadline = text(candidate.proposedHeadline || candidate.topic);
  const suppliedSourceText = sources.map((item) => {
    const article = articleByUrl.get(canonicalUrl(item.url)) || item;
    return `${sourcePlainText(article.title)} ${sourcePlainText(article.description)}`;
  }).join(' ');
  const suppliedSourcesSupportNovelty = /\b(new|newly|latest|recently|just released|just published|just announced)\b/i.test(suppliedSourceText);
  const headline = suppliedSourcesSupportNovelty
    ? rawHeadline
    : text(rawHeadline
        .replace(/\bnew\s+(guidance|recommendations?|framework|standard|report|advisory|directive|policy|release|announcement)\b/gi, '$1')
        .replace(/\blatest\s+(guidance|recommendations?|framework|standard|report|advisory|directive|policy|release|announcement)\b/gi, '$1'));
  const headlineTemporalLanguageNormalized = headline !== rawHeadline;
  const topic = text(candidate.topic || headline);
  const claimScopeText = `${topic} ${headline} ${candidate.whyNow} ${candidate.contentAngle}`;
  const requiresPrimarySource = /\b(malware|ransomware|threat actor|attack campaign|cyberattack|breach|vulnerability|exploit|zero[- ]day|cve-|security advisory|product announcement|product launch)\b/i.test(claimScopeText);
  const familyEvidence = sources.length >= 2 && (
    (primaryCount >= 1 && credibleCount >= 1) ||
    primaryCount >= 2 ||
    credibleCount >= 2
  );
  const primarySourceRequirementMet = !requiresPrimarySource || primaryCount >= 1;
  const semanticAnchor = `${topic} ${headline}`;
  const semanticMatches = sources.map((item) => {
    const article = articleByUrl.get(canonicalUrl(item.url)) || item;
    return semanticMatchTerms(semanticAnchor, article);
  });
  const sharedSemanticTerms = semanticMatches.length >= 2
    ? semanticMatches.slice(1).reduce(
        (shared, terms) => shared.filter((term) => terms.includes(term)),
        [...semanticMatches[0]]
      )
    : [];
  const topicTerms = semanticTokens(topic);
  const topicSemanticMatches = sources.map((item) => {
    const article = articleByUrl.get(canonicalUrl(item.url)) || item;
    return semanticMatchTerms(topic, article);
  });
  const topicSharedSemanticTerms = topicSemanticMatches.length >= 2
    ? topicSemanticMatches.slice(1).reduce(
        (shared, terms) => shared.filter((term) => terms.includes(term)),
        [...topicSemanticMatches[0]]
      )
    : [];
  const topicSharedTermCoverage = topicTerms.length
    ? topicSharedSemanticTerms.length / topicTerms.length
    : 0;
  const semanticEvidenceAligned =
    semanticMatches.length >= 2 &&
    semanticMatches.every((terms) => terms.length > 0) &&
    sharedSemanticTerms.length > 0 &&
    topicSharedTermCoverage >= 0.5;
  const strongEvidence = familyEvidence && primarySourceRequirementMet && semanticEvidenceAligned && (!bundleRequired || bundleValid);
  if (!headline || !topic) {
    validationStats.rejectedMissingTopic += 1;
    if (validationStats.rejectedCandidates.length < 15) {
      validationStats.rejectedCandidates.push({
        requestedSection,
        topic: 'Untitled candidate',
        reason: 'Candidate did not contain a usable topic or headline',
      });
    }
    return null;
  }
  validationStats.normalizedCandidateCount += 1;

  const absoluteClaim = absolutePattern.test(
    `${headline} ${candidate.whyNow} ${candidate.openingHook}`
  );
  const genericTopic = themeSet.has(normalized(topic)) || themeSet.has(normalized(headline));
  const claimText = `${headline} ${candidate.whyNow} ${candidate.contentAngle} ${candidate.openingHook}`;
  const evidenceText = sources.map((item) => item.supportingEvidence).join(' ');
  const timeSensitivePattern = /\b(this|last|past)\s+(week|month|year)\b|\b(today|yesterday|new|newly|latest|recently|just released|published|released|announced)\b/i;
  const unsupportedTemporalClaim = timeSensitivePattern.test(claimText) && !timeSensitivePattern.test(suppliedSourceText);
  let risks = list(candidate.editorialRisks).map(text).filter(Boolean);
  if (bundleValid) {
    const staleCorroborationRisk = /\b(single[- ]source|no independent corroboration|independent corroboration lacking|same source family|insufficient corroboration)\b/i;
    risks = risks.filter((risk) => !staleCorroborationRisk.test(risk));
  }
  if (bundleRequired && !evidenceBundleId) risks.push('Verified-section candidate did not select an evidence bundle');
  else if (bundleRequired && !bundleValid) risks.push('Selected evidence bundle was missing or unqualified');
  if (!semanticEvidenceAligned) risks.push('Candidate topic is not sufficiently supported by both evidence sources');
  if (genericTopic) risks.push('Topic is too broad and must be reframed around a concrete leadership decision or current event');
  if (unsupportedTemporalClaim) risks.push('Time-sensitive claim is not supported by the copied evidence excerpts');
  if (sources.length > 1 && primaryCount + credibleCount < 2) risks.push('Multiple URLs belong to the same source family');
  if (requiresPrimarySource && !primarySourceRequirementMet) risks.push('Threat, vulnerability, incident, or product claim lacks a primary source');
  if (!strongEvidence) risks.push('Insufficient corroboration for editorial selection');
  if (absoluteClaim) risks.push('Absolute claim requires editorial revision');
  if (sources.some((item) => item.snippetMayBeTruncated)) {
    risks.push('Source evidence appears truncated and requires direct source review');
  }
  const blockingRiskPattern = /\b(single[- ]source|no independent corroboration|independent corroboration lacking|promotional|unverified|same source family|insufficient corroboration|evidence bundle|do not share a substantive|not sufficiently supported)\b/i;
  const unresolvedBlockingRisk = risks.some((risk) => blockingRiskPattern.test(risk));

  let sourceQuality = 1;
  if (primaryCount >= 1 && credibleCount >= 1) sourceQuality = 5;
  else if (primaryCount >= 2 || credibleCount >= 2) sourceQuality = 4;
  else if (primaryCount === 1 || credibleCount === 1) sourceQuality = 3;
  else if (sources.length >= 2) sourceQuality = 2;

  const raw = candidate.scores || {};
  const scoreValues = {
    audienceFit: integer(raw.audienceFit, 0, 20),
    businessImpact: integer(raw.businessImpact, 0, 20),
    timeliness: integer(raw.timeliness, 0, 15),
    novelty: integer(raw.novelty, 0, 15),
    engagementPotential: integer(raw.engagementPotential, 0, 15),
    actionability: integer(raw.actionability, 0, 10),
    sourceQuality,
  };

  let scoreCap = strongEvidence ? 94 : sources.length >= 2 ? 79 : 69;
  if (absoluteClaim || unsupportedTemporalClaim) scoreCap = Math.min(scoreCap, 79);
  if (requestedSection === 'watchlist') scoreCap = Math.min(scoreCap, 79);
  const calibrated = reduceToCap(scoreValues, scoreCap);

  let confidenceCap = strongEvidence ? 0.92 : sources.length >= 2 ? 0.75 : 0.6;
  if (absoluteClaim || unsupportedTemporalClaim) confidenceCap = Math.min(confidenceCap, 0.7);
  const requestedConfidence = Number(candidate.confidence);
  const derivedConfidence = Math.max(0.2, calibrated.total / 100);
  const confidence = Math.max(
    0.2,
    Math.min(
      Number.isFinite(requestedConfidence) && requestedConfidence > 0
        ? requestedConfidence
        : derivedConfidence,
      confidenceCap
    )
  );

  const relatedMeetingThemes = list(candidate.relatedMeetingThemes)
    .map(text)
    .filter((theme) => themeSet.has(normalized(theme)));

  const section = requestedSection !== 'watchlist' && strongEvidence && !absoluteClaim && !unsupportedTemporalClaim && !genericTopic && !unresolvedBlockingRisk
    ? requestedSection
    : 'watchlist';

  function defaultAudience(value) {
    if (/\b(ai|governance|compliance|risk)\b/i.test(value)) {
      return ['CTO', 'CISO', 'Risk and compliance leaders'];
    }
    if (/\b(identity|network|security|exposure|threat)\b/i.test(value)) {
      return ['CISO', 'Security leaders', 'Infrastructure leaders'];
    }
    if (/\b(cloud|infrastructure|digital twin|resilience|recovery)\b/i.test(value)) {
      return ['CTO', 'Infrastructure leaders', 'Enterprise architects'];
    }
    return ['Technology leaders', 'Security leaders', 'Business executives'];
  }

  const suppliedAudience = list(candidate.targetAudience).map(text).filter(Boolean);

  const safeWatchlist = section === 'watchlist';

  return {
    section,
    candidate: {
      rank: 0,
      topic,
      proposedHeadline: safeWatchlist ? `Research needed: ${topic}` : headline,
      relatedMeetingThemes,
      whyNow: safeWatchlist
        ? 'Current coverage surfaced this topic, but the supplied records do not provide qualifying corroboration.'
        : text(candidate.whyNow),
      targetAudience: suppliedAudience.length ? suppliedAudience : defaultAudience(topic),
      contentAngle: safeWatchlist
        ? 'Identify a primary authoritative source and credible independent corroboration before developing an editorial angle.'
        : text(candidate.contentAngle),
      openingHook: safeWatchlist ? 'Not approved for drafting.' : text(candidate.openingHook),
      recommendedFormat: safeWatchlist ? 'Research queue item' : text(candidate.recommendedFormat),
      evidenceBundleId: bundleValid ? evidenceBundleId : '',
      sources,
      scores: { ...calibrated.scores, total: calibrated.total },
      confidence,
      verificationStatus: strongEvidence && !absoluteClaim && !unsupportedTemporalClaim && !genericTopic && !unresolvedBlockingRisk
        ? 'verified'
        : 'needs_verification',
      editorialRisks: [...new Set(risks)],
      validation: {
        validatedSourceCount: sources.length,
        primarySourceCount: sources.filter((item) => item.sourceTier === 'primary').length,
        credibleIndependentSourceCount: sources.filter((item) => item.sourceTier === 'credible_independent').length,
        primarySourceFamilyCount: primaryCount,
        credibleIndependentSourceFamilyCount: credibleCount,
        independentSourceFamilyCount: primaryCount + credibleCount,
        bundleRequired,
        bundleValid,
        bundleType: bundleValid ? text(selectedBundle.bundleType) : '',
        semanticEvidenceAligned,
        sharedSemanticTerms,
        semanticMatches,
        topicTerms,
        topicSharedSemanticTerms,
        topicSharedTermCoverage,
        headlineTemporalLanguageNormalized,
        familyEvidence,
        requiresPrimarySource,
        primarySourceRequirementMet,
        unresolvedBlockingRisk,
        strongEvidence,
        scoreCap,
      },
    },
  };
}


function deterministicFallbackTopic(bundle) {
  const records = list(bundle.records);
  const primary = records.find((item) => classifySource(item.url) === 'primary');
  const credible = records.find((item) => classifySource(item.url) === 'credible_independent');
  if (!primary || !credible) return '';

  const sourceTermSets = records.map((article) => new Set(
    semanticTokens(`${article.title || ''} ${article.description || ''}`)
  ));
  if (sourceTermSets.length < 2) return '';
  const sharedTerms = [...sourceTermSets[0]].filter((term) =>
    sourceTermSets.slice(1).every((terms) => terms.has(term))
  );
  if (sharedTerms.length < 3) return '';
  const sharedSet = new Set(sharedTerms);

  const title = sourcePlainText(primary.title)
    .replace(/\s+\|\s+[^|]+$/g, '')
    .replace(/\s+-\s+(?:SecurityWeek|Help Net Security|Network World|CyberScoop)$/i, '')
    .trim();
  const words = title.split(/\s+/).filter(Boolean);
  let best = null;

  for (let length = 3; length <= Math.min(10, words.length); length++) {
    for (let start = 0; start + length <= words.length; start++) {
      const phrase = words.slice(start, start + length).join(' ')
        .replace(/^[^A-Za-z0-9]+|[^A-Za-z0-9]+$/g, '');
      const terms = semanticTokens(phrase);
      if (!terms.length) continue;
      const sharedCount = terms.filter((term) => sharedSet.has(term)).length;
      const coverage = sharedCount / terms.length;
      if (sharedCount < 3 || coverage < 0.6) continue;
      const score = sharedCount * 10 + terms.length - length * 0.1;
      if (!best || score > best.score) best = { phrase, score };
    }
  }
  return best ? best.phrase : '';
}

function deterministicFallbackCandidate(bundle) {
  const topic = deterministicFallbackTopic(bundle);
  if (!topic) return null;
  return {
    rank: 1,
    topic,
    proposedHeadline: `What leaders should review in ${topic}`,
    relatedMeetingThemes: list(bundle.relatedMeetingThemes),
    whyNow: 'A primary source and credible independent coverage address the same operating question.',
    targetAudience: ['Technology leaders', 'Security leaders', 'Business executives'],
    contentAngle: 'Review the scope, ownership, decision criteria, and validation questions raised by the cited sources.',
    openingHook: 'Two independent sources point to an operating question leaders should review.',
    recommendedFormat: 'LinkedIn post',
    evidenceBundleId: text(bundle.bundleId),
    sources: list(bundle.records).map((article) => ({
      title: article.title,
      url: article.url,
      publisher: article.publisher,
      publishedAt: article.publishedAt,
      supportingEvidence: '',
    })),
    scores: {
      audienceFit: 14,
      businessImpact: 14,
      timeliness: 8,
      novelty: 8,
      engagementPotential: 10,
      actionability: 8,
      sourceQuality: 5,
      total: 67,
    },
    confidence: 0.72,
    verificationStatus: 'verified',
    editorialRisks: [],
  };
}

const sections = { themeAligned: [], emerging: [], watchlist: [] };
const seenTopics = new Set();

for (const requestedSection of ['themeAligned', 'emerging', 'watchlist']) {
  for (const rawCandidate of list(parsed[requestedSection])) {
    validationStats.rawCandidateCount += 1;
    const normalizedCandidate = normalizeCandidate(rawCandidate, requestedSection);
    if (!normalizedCandidate) continue;
    const key = normalized(normalizedCandidate.candidate.topic);
    if (!key || seenTopics.has(key)) {
      validationStats.duplicateTopicCount += 1;
      continue;
    }
    seenTopics.add(key);

    const destination = normalizedCandidate.section;
    const limit = destination === 'watchlist' ? 5 : 5;
    if (sections[destination].length < limit) {
      sections[destination].push(normalizedCandidate.candidate);
    }
  }
}

if (sections.themeAligned.length + sections.emerging.length === 0) {
  for (const bundle of list(source.qualifiedEvidenceBundles)) {
    if (sections.themeAligned.length >= 3) break;
    if (bundle.qualified !== true) continue;
    const fallback = deterministicFallbackCandidate(bundle);
    if (!fallback) continue;
    const normalizedCandidate = normalizeCandidate(fallback, 'themeAligned');
    if (!normalizedCandidate || normalizedCandidate.section !== 'themeAligned') continue;
    const key = normalized(normalizedCandidate.candidate.topic);
    if (!key || seenTopics.has(key)) continue;
    seenTopics.add(key);
    sections.themeAligned.push(normalizedCandidate.candidate);
    validationStats.deterministicFallbackCandidateCount += 1;
  }
}

for (const candidates of Object.values(sections)) {
  candidates.sort((a, b) => b.scores.total - a.scores.total);
  candidates.forEach((candidate, index) => { candidate.rank = index + 1; });
}

const candidateCount =
  sections.themeAligned.length + sections.emerging.length + sections.watchlist.length;
const verifiedCandidateCount = sections.themeAligned.length + sections.emerging.length;
const outputStatus = candidateCount === 0
  ? 'insufficient_evidence'
  : verifiedCandidateCount === 0
    ? 'watchlist_only'
    : 'ready';

const generatedAt = new Date().toISOString();
const dateParts = Object.fromEntries(
  new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
